class FeetechBus:
    def __init__(self, port, baud=1_000_000, timeout=0.02, ser=None):
        # ser 给模拟器用（sim_bus.SimSerial），真机走串口
        self.ser = ser if ser is not None else serial.Serial(port, baud, timeout=timeout, write_timeout=0.1)
        # 串口互斥锁。别叫 self.lock：会盖住下面的 lock(sid)「加 EEPROM 锁」方法（2026-09-20 真机踩到）
        self._io = threading.Lock()
        # 原始收发记录：设一个 trace(文本) 回调就开始记。飞特不支持的操作照样回"成功"，
        # 只有对着十六进制才分得清「真做了」和「装作做了」。10 Hz 的状态轮询不记，不然日志全是它
        self.trace = None
        self.trace_skip = {SYNC_READ, SYNC_WRITE}
        self._last = (None, None)
        self.stats = {"tx": 0, "rx_ok": 0, "timeout": 0, "bad_checksum": 0, "bad_id": 0}

def read(self, sid, addr, n):
    with self._io:
        self._send(sid, READ, bytes([addr, n]))
        _, err, params = self._read_status(sid)
        if len(params) != n:
            raise BusError(f"id {sid} 读地址 {addr} 起 {n} 字节，只回了 {len(params)} 字节")
        return err, params

def write(self, sid, addr, data, wait=True):
    with self._io:
        self._send(sid, WRITE, bytes([addr]) + bytes(data))
        if not wait or sid == BROADCAST:
            return None
        try:
            _, err, _ = self._read_status(sid)
            return err
        except BusTimeout:
            # 应答级别 0 时写指令不回包，不算错；调用方拿到 None 自己判断
            return None

def write_u8(self, sid, addr, v):
    return self.write(sid, addr, [v & 0xFF])

def write_u16(self, sid, addr, v):
    return self.write(sid, addr, struct.pack("<H", v & 0xFFFF))

def read_u8(self, sid, addr):
    return self.read(sid, addr, 1)[1][0]

def read_u16(self, sid, addr):
    return struct.unpack("<H", self.read(sid, addr, 2)[1])[0]

def sync_write(self, addr, length, id_values):
    """id_values: [(id, bytes), ...]，每个 bytes 长度 = length。"""
    params = bytes([addr, length])
    for sid, data in id_values:
        assert len(data) == length
        params += bytes([sid]) + bytes(data)
    with self._io:
        self._send(BROADCAST, SYNC_WRITE, params)

def sync_read(self, ids, addr, n):
    """返回 {id: (err, params) 或 None}，顺序按 ids。任何一颗超时不影响后面的。"""
    out = {}
    with self._io:
        self._send(BROADCAST, SYNC_READ, bytes([addr, n]) + bytes(ids))
        for sid in ids:
            try:
                _, err, params = self._read_status(sid)
                out[sid] = (err, params) if len(params) == n else None
            except BusError:
                out[sid] = None
    return out

def reboot(self, sid):

def read_states_with_imu(ids, service):
    """--imu-bus：跟主控每 tick 同一条 sync_read（地址 56、长度 15、200 排第一），
    舵机状态照旧解，200 的块喂给 service。200 连续不应答时 service 会让它暂时出列。"""
    import imu_bus
    servo_ids = [i for i in ids if i != imu_bus.IMU_ID]
    with_imu = service.include_in_sync()
    if not with_imu and service.due_probe():
        if service.probe_result(BUS.ping(imu_bus.IMU_ID) is not None):
            log("ID 200 的 PING 有应答了，重新跟舵机一起读", "IMU")
    if isinstance(BUS, FakeBus):
        # 虚拟小板：启动参数 --fake --imu-bus 时 fallback_fake 挂上，或者页面「模拟」里接上
        st = BUS.states(servo_ids)
        got = BUS.sync_read([imu_bus.IMU_ID], imu_bus.BLOCK_ADDR, imu_bus.BLOCK_LEN) if with_imu else {}
    else:
        # 2026-10-31 本机补丁（v0.15.4）：200 改独立单播 READ——当前 v0.3 板固件（replica
        # 0.2.0）SYNC_READ 应答弱（实测单 ID ~30%、多 ID 0%），单播 READ 100% 且 1ms 快答；
        # 舵机照旧整表 sync_read，IMU 缺答不再连累舵机帧。板②（kit v1 固件）SYNC_READ
        # 正常，换回时恢复 ids_sent 混读形态即可。
        got = BUS.sync_read(servo_ids, imu_bus.BLOCK_ADDR, imu_bus.BLOCK_LEN) if servo_ids else {}
        st = {sid: (feetech.FeetechBus._decode_state(*got[sid]) if got.get(sid) else None) for sid in servo_ids}
        if with_imu:
            try:
                _, blk = BUS.read(imu_bus.IMU_ID, imu_bus.BLOCK_ADDR, imu_bus.BLOCK_LEN)
                got[imu_bus.IMU_ID] = (imu_bus.BLOCK_ADDR, blk)
            except Exception:
                pass  # 缺答交给 service.feed(None) 计 miss，不连累上面的舵机帧
    v = got.get(imu_bus.IMU_ID)
    if with_imu or v is not None:
        service.feed(v[1] if v else None)
    return st

